{
  "payment_source": {
    "paypal": {
      "description": "Recourse: saved PayPal for agent checkout",
      "usage_pattern": "IMMEDIATE",
      "usage_type": "MERCHANT",
      "customer_type": "CONSUMER",
      "permit_multiple_payment_tokens": false,
      "experience_context": {
        "brand_name": "Recourse",
        "return_url": "{{return_url}}",
        "cancel_url": "{{cancel_url}}"
      }
    }
  }
}

{
  "auth_algo": "<paypal-auth-algo header>",
  "cert_url": "<paypal-cert-url header>",
  "transmission_id": "<paypal-transmission-id header>",
  "transmission_sig": "<paypal-transmission-sig header>",
  "transmission_time": "<paypal-transmission-time header>",
  "webhook_id": "{{webhook_id}}",
  "webhook_event": {
    "replace": "with the event body exactly as received"
  }
}

{
  "detail": {
    "invoice_number": "{{invoice_number}}",
    "reference": "RCS-CASE-TEST",
    "currency_code": "{{currency}}",
    "note": "Recourse ruling: agent fault. Reimbursement of the buyer refund.",
    "payment_term": {
      "term_type": "DUE_ON_RECEIPT"
    }
  },
  "invoicer": {
    "business_name": "Recourse sandbox merchant"
  },
  "primary_recipients": [
    {
      "billing_info": {
        "email_address": "{{operator_email}}"
      }
    }
  ],
  "items": [
    {
      "name": "Agent fault liability",
      "quantity": "1",
      "unit_amount": {
        "currency_code": "{{currency}}",
        "value": "25.00"
      },
      "unit_of_measure": "AMOUNT"
    }
  ]
}

{
  "send_to_invoicer": false,
  "send_to_recipient": true,
  "subject": "Recourse: agent fault liability invoice (sandbox)"
}

{
  "buyer_email": "{{buyer_email}}",
  "text": "Running shoes, US men's 10, under $120, Nike or Asics, delivered by Friday"
}

{
  "kind": "agent.note",
  "payload": {
    "mandate_id": "{{mandate_id}}",
    "note": "agent compared the substitute with the mandate"
  }
}
